class LoggerConfig:
    def __init__(self, log_level=LOG_LEVEL): self.log_level = log_level
    def setup(self):
        logger.remove()
        logger.add(sys.stdout, level=self.log_level)
def get_logger():
    LoggerConfig().setup()
    return logger
